INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('a4189dc7-d3d2-5dd7-a80a-60fb72362636', 'eb24593e-f0c9-5d6c-8aa2-a423fb185155', 'tr', $h$Yamada® Uyumlu Yedek Parça$h$, $h$yamada-uyumlu-yedek-parca$h$, $h$Yamada® Uyumlu Yedek Parça$h$, $h$<div> <div><p>HD Marine valf topu, valf yuvası, diyaframı ve valf halkaları gibi Yamada yedek parçalara ürünlerine güvenilir şekilde ulaşmanız için hizmet vermektedir. En yaygın kullanılan ve tercih edilen Neoprene, Nitrile, PTFE, FKM/ Viton, EPDM, Santopren, Hytrel, N-fit gibi malzemeleri ve ürünleri kullanım alanlarına göre müşterileriyle buluşturmaktadır. Havayla Çalışan Çift Diyaframlı pompalarınızın sorunsuz ve yüksek performansla çalışması için doğru yedek parçayı temin etmelisiniz. Bakım, onarım ve servis hizmetlerinde ürünlerin zarar görmemesi için gerekli özeni göstermelisiniz.</p></div> </div><div> <div><p>Yamada diyafram yedek parça ürünlerinde endüstri alanlarına göre kullanılması gereken malzeme değişiklik gösterecektir. HD Marine en yaygın kullanılan malzeme çeşitlerinden <strong>Yamada Pumps Diaphragm PTFE</strong> yedek parçasını gibi ürünleri müşterilerine sunmaktadır. PTFE/TFM aromatik veya klorlu hidrokarbon, asit, keton ve asetat gibi agresif sıvıları pompalarken tercih etmeniz gerekir. <strong>Poliüretan, Santopren, Hytrel vb</strong>. malzeme çeşitlerini de kullanacağınız yere göre tercih edebilirsiniz. <strong>Yamada-dıaphragms</strong> kaliteli bir çalışma için düzenli kontrol edilmeli ve gerekli tamirleri bilirkişiler tarafından yapılmalıdır.</p><p>Valf topları havayla çalışan çift diyaframlı pompanın düzgün çalışması için kontrol edilmeli ve bakımları yapılmalıdır. Çünkü sıvıyı pompalarken valf toplarının ileri ve geriye hareket etme işlevini düzgün yerine getirmesi gerekir. HD Marine<strong> </strong>kullanılacak alanları birbirinden farklı olan Yamada Balls yedek parça ürünlerini müşterilerinin ihtiyacını karşılamak için temin etmektedir. <strong>Yamada Balls FKM, Yamada Balls Nitrile ve Yamada Balls PTFE </strong>en yaygın kullanılan malzemelerdir. <strong>Yamada Balls FKM</strong>, aşırı ısı gerektiren alanlarda, <strong>Yamada Balls Nitrile</strong> yedek parçasını petrol/yağ bazlı, akaryakıt, benzin gibi sıvıları içeren uygulamalarda, <strong>Yamada Balls PTFE </strong>agresif sıvıları pompalarken,<strong> Yamada Balls </strong>Neopren ise agresif olmayan uygulamalarda kullanım için tercih etmelisiniz.</p><p><strong>Yamada o-ring</strong> yedek parçalarında kullanılacağı yere, endüstri alanına uygun geniş boyut ve malzeme seçeneği vardır. Örneğin <strong>Yamada o-ring PTFE</strong> yemek parçası agresif asit, baz, alkol, yağlara karşı çok iyi kimyasal direnci ardır. Yüksek ve düşük sıcaklara dayanıklı olmasıyla da en yaygın tercih edilen o-ring malzemelerindendir.</p><p>Havayla çalışan çift diyaframlı pompaların çalışma sisteminin düzgün ve sağlıklı ilerleyebilmesi için her bir parçanın birlikte uyum içerisinde çalışması gerekmektedir. Düzgün, kaliteli ve sorunsuz bir çalışma sağlamak istiyorsanız valf yuvası, topu, diyaframı, donanımı, halkası ve genel olarak pompa sistemini kontrol etmelisiniz. Buna ek olarak da ürünün performansını düşürmemek için düzenli aralıklarla Yamada yedek parça ürünlerini değiştirmelisiniz. HD Marine firması, ihtiyaç duyduğunuz Yamada yedek parçalarını size ulaştırmak için profesyonel bir ekip ile hizmet vermektedir.</p></div> </div>$h$, NULL, $h$Yamada® Uyumlu Yedek Parça | HD Marine$h$, $h$HD Marine valf topu, valf yuvası, diyaframı ve valf halkaları gibi Yamada yedek parçalara ürünlerine güvenilir şekilde ulaşmanız için hizmet vermektedir.…$h$, 'reviewed'),
('131ce671-c4d3-51b3-a5a0-f02f77783641', '39089535-f187-5347-8fb3-f35edf83f91b', 'tr', $h$Havalı Gres Pompası 10 Kg – 2110$h$, $h$havali-gres-pompasi-10-kg-2110$h$, $h$Neden 2110 Havalı Gres Pompası ?$h$, $h$<div> <div><p>45:1 basınç oranına sahip hava ile çalışan gres pompası, 10 kg gres yağı kapasitesi sunar. Kısa mesafeli yüksek basınçlı yağlama için idealdir. Dört adet döner tekerlek ile kolayca yön verirsiniz. Pompada çelik tel takviyeli hidrolik hortum kullanır. Piston çapı Ø62 mm’dir. Yağ baskı tablası ve yayı, hazne içindeki yağı sıkılaştırır. Bu özellik, yüksek viskoziteli yağlarda ve soğuk bölgelerde pompa beslemesini kolaylaştırır. Ayrıca gres tabanca girişindeki Z mafsal, hortum ve tabancayı daha kolay kullanmanızı sağlar. Çalışma basıncı minimum 6 bar, maksimum 8 bar arasında değişir. Pompanın performansını ve ömrünü artırmak için filtrelenmiş ve yağlanmış hava kullanın. Opsiyonel aksesuarlar işlevselliğini artırır.</p></div> </div>$h$, NULL, $h$Havalı Gres Pompası 10 Kg – 2110 | HD Marine$h$, $h$45:1 basınç oranına sahip hava ile çalışan gres pompası, 10 kg gres yağı kapasitesi sunar. Kısa mesafeli yüksek basınçlı yağlama için idealdir. Dört adet…$h$, 'reviewed'),
